<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';
import {UsbOutlined,PrinterOutlined,LockOutlined,SaveOutlined,LinkOutlined} from '@ant-design/icons-vue';
import {api,errorText} from '../api';
import {boot,status} from '../store';

const error=ref(''),notice=ref(''),busy=ref(false),code=ref(''),edit=ref(false),pairing=ref('');
const devices=ref<{serialPorts:string[];printers:string[]}>({serialPorts:[],printers:[]});
const form=reactive({protocol:boot.value?.protocol||'SOHE_RS232_V101',serialPort:boot.value?.serialPort||'',baudRate:boot.value?.baudRate||9600,httpScaleUrl:boot.value?.httpScaleUrl||'http://127.0.0.1:33582',httpUnit:boot.value?.httpUnit||'',httpStableField:boot.value?.httpStableField||'',printerName:boot.value?.printerName||'',localTicketsEnabled:boot.value?.localTicketsEnabled||false,paperWidthMm:boot.value?.paperWidthMm||60,paperHeightMm:boot.value?.paperHeightMm||40,traceUrlTemplate:boot.value?.traceUrlTemplate||''});
async function save():Promise<void>{busy.value=true;error.value='';notice.value='';try{await api('/workstation/config','',form,{'X-Maintenance-Code':code.value});notice.value='配置已保存。请结束当前作业后重启设备服务，新配置统一生效。';edit.value=false;code.value='';}catch(value){error.value=errorText(value);}finally{busy.value=false;}}
async function activate():Promise<void>{busy.value=true;error.value='';try{await api('/activate','',{pairingCode:pairing.value},{'X-Maintenance-Code':code.value});notice.value='设备授权已更新。可返回任务页面获取授权任务。';pairing.value='';}catch(value){error.value=errorText(value);}finally{busy.value=false;}}
onMounted(async()=>{try{devices.value=await api('/workstation/devices');}catch(value){error.value=errorText(value);}});
</script>

<template>
  <section class="page-heading"><div><div class="eyebrow">工作台维护</div><h1>设备设置</h1><p>查看秤与打印机。修改配置需维护码，重启后统一生效。</p></div><a-tag>{{boot?.hardwareTest?'实机测试设备':boot?.localTest?'隔离演练设备':'现场设备'}}</a-tag></section>
  <a-alert v-if="error" :message="error" type="error" show-icon class="section-gap"/><a-alert v-if="notice" :message="notice" type="success" show-icon class="section-gap"/>
  <div class="device-facts panel"><div><span>设备编码</span><strong>{{boot?.deviceCode||'未配置'}}</strong></div><div><span>工作台</span><strong>{{boot?.stationCode||'未配置'}}</strong></div><div><span>本机版本</span><strong>{{boot?.version}}</strong></div><div><span>计量规则</span><strong>按斤记录 · 无固定软件量程门槛</strong></div></div>
  <div class="settings-grid"><section class="panel settings-card"><div class="settings-heading"><usb-outlined class="workstation-icon"/><h2>电子秤连接</h2></div><a-form layout="vertical" :disabled="!edit||busy"><a-form-item label="读取协议"><a-select v-model:value="form.protocol" :options="[{value:'SOHE_RS232_V101',label:'首衡外置 RS232 连续输出'},{value:'SOHE_AD',label:'首衡内置 AD（净毛重待核实）'},{value:'SOHE_HTTP',label:'首衡本机 HTTP 辅助程序'}]"/></a-form-item><template v-if="form.protocol==='SOHE_HTTP'"><a-form-item label="厂家本机地址"><a-input v-model:value="form.httpScaleUrl"/></a-form-item><div class="form-grid"><a-form-item label="已核实重量单位"><a-select v-model:value="form.httpUnit" :options="[{value:'',label:'尚未核实'},{value:'kg',label:'kg'},{value:'g',label:'g'},{value:'sj',label:'斤（sj）'}]"/></a-form-item><a-form-item label="厂家稳定布尔字段"><a-input v-model:value="form.httpStableField" placeholder="无可信字段时留空"/></a-form-item></div></template><template v-else><a-form-item label="串口"><a-select v-model:value="form.serialPort" :options="devices.serialPorts.map(value=>({value,label:value}))" placeholder="选择设备管理器中的串口"/></a-form-item><a-form-item label="波特率"><a-select v-model:value="form.baudRate" :options="[9600,19200,38400,57600,115200].map(value=>({value,label:String(value)}))"/></a-form-item></template></a-form><p class="muted">稳定和净重须来自可信设备信息。去皮、置零与标定配置不在此页面开放。</p></section>
    <section class="panel settings-card"><div class="settings-heading"><printer-outlined class="workstation-icon"/><h2>本地称重凭条</h2></div><a-form layout="vertical" :disabled="!edit||busy"><a-form-item label="Windows打印机"><a-select v-model:value="form.printerName" :options="devices.printers.map(value=>({value,label:value}))" placeholder="选择已安装驱动的打印队列"/></a-form-item><div class="form-grid"><a-form-item label="纸张宽度（mm）"><a-input-number class="paper-input" v-model:value="form.paperWidthMm" :min="40" :max="110"/></a-form-item><a-form-item label="纸张高度（mm）"><a-input-number class="paper-input" v-model:value="form.paperHeightMm" :min="40" :max="300"/></a-form-item></div><a-form-item label="启用本地待同步凭条"><a-switch v-model:checked="form.localTicketsEnabled"/><span class="switch-help">每筐保存后打印</span></a-form-item><a-form-item label="溯源查询地址（预留）"><a-input v-model:value="form.traceUrlTemplate" :maxlength="240" placeholder="尚未确定，留空即可"/><p class="muted">平台提供公开HTTPS查询页后配置，地址中使用 {eventKey} 关联记录。仅对新票生效。</p></a-form-item></a-form><a-alert type="info" show-icon :message="boot?.hardwareTest?'本模式读取真实秤，手动保存会打印测试标签；不是正式业务记录。':'本地凭条标记待同步，不作为平台正式业务确认。普通演练只模拟打印，不出纸。'"/></section>
  </div>
  <section class="panel maintenance-panel"><div class="settings-heading"><lock-outlined class="workstation-icon"/><h2>维护操作</h2></div><p class="muted">普通称重员可查看设备信息。维护码由现场实施人员在本机配置。</p><div class="maintenance-actions"><a-input-password v-model:value="code" placeholder="输入维护码" :maxlength="200" autocomplete="off" class="maintenance-code"/><a-button v-if="!edit" :disabled="!boot?.maintenanceAvailable||!code" @click="edit=true">进入配置编辑</a-button><a-button v-else type="primary" :loading="busy" @click="save"><save-outlined class="workstation-icon"/>保存配置</a-button><a-button v-if="edit" @click="edit=false">取消编辑</a-button></div><div v-if="code" class="pairing-line"><a-input-password v-model:value="pairing" placeholder="设备一次性配对码" autocomplete="off" class="maintenance-code"/><a-button :disabled="!pairing" :loading="busy" @click="activate"><link-outlined class="workstation-icon"/>设备配对</a-button></div></section>
</template>
